-- 452 — 工作台 / 后台开发登录 / 数据规则编辑器 / 插件 / 访问面片段端点的文案词条。
--
-- 范围（迁移 452 是本批唯一新增词条的地方）：
--   · workbench.ui.*          工作台画布模板（layout.html）的取词
--   · workbench.title/mode.*  画布标题与双轨状态条（Go 侧取词后作 data 传给模板）
--   · workbench.outline.*     结构树（Go 拼 HTML）的按钮提示
--   · workbench.inspector.*   检查器分组标题 / 字段 Label / 占位符 / 下拉选项 / 重复项面板
--   · workbench.err.*         画布出口的受控短句（首批 8 条长文案已在迁移 292）
--   · site.fragment.err.*     访问面片段端点固定短句（首批 5 条语义错误已在迁移 409）
--   · plugin.*                插件模块的页面与装配错误文案
--   · admin.dev_login.*       开发登录（debug-only 端点）的 JSON/文本出口
--   · admin.datarules.editor.field_*  数据规则编辑器的字段下拉空选项
--
-- 为什么每条都成对给中英：sys_i18n 的主键是 (item_key, lang)，英文站点取 en-US 一行；
-- zh-CN 的值与代码里的中文兜底逐字一致 —— 这样「i18n 未初始化」与「词条已 seed」
-- 两种环境下响应体相同（否则测试里看到兜底长句、生产里看到词条）。占位符用 {name}。
INSERT INTO sys_i18n (item_key, lang, item_value, http_code, category, remark, status, create_time, update_time)
